    def _schedule_ambient(self) -> None:
        """ç”¨éšæœºé—´éš”å®‰æ’å…­æ¯›ä¸»åŠ¨å‡ºç°ï¼Œä¿æŒå­˜åœ¨æ„Ÿä½†é¿å…é¢‘ç¹æ‰“æ‰°ã€‚"""

